selector_to_html = {"a[href=\"#testing-and-validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Testing and validation<a class=\"headerlink\" href=\"#testing-and-validation\" title=\"Link to this heading\">#</a></h2><p>Before testing, you need to execute <code class=\"docutils literal notranslate\"><span class=\"pre\">source</span> <span class=\"pre\">~/env_setup.sh</span></code>. The content of this script is shown above.</p><p>Refer to <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.3.x/.github/workflows/aipu-build-and-test.yml\">Tests of aipu backend</a></p>", "a[href=\"#arm-china-aipu3-3\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ARM China\uff08\u5b89\u8c0b\u79d1\u6280\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.3.x/third_party/aipu/\">aipu</a>3.3<a class=\"headerlink\" href=\"#arm-china-aipu3-3\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (for the x64 CPU simulation environment)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later installation steps.</p>", "a[href=\"#source-free-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 Source-free Installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree</span></code> is already installed in the preinstalled image.</p>", "a[href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 Use the preinstalled image (for the x64 CPU simulation environment)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later installation steps.</p>", "a[href=\"#build-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Build from Source<a class=\"headerlink\" href=\"#build-from-source\" title=\"Link to this heading\">#</a></h2><h3>2.1 Manually download the FlagTree dependencies<a class=\"headerlink\" href=\"#manually-download-the-flagtree-dependencies\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to download the dependencies which will be fetched automatically during the build.</p>", "a[href=\"#quick-start\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (for the x64 CPU simulation environment)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later installation steps.</p>", "a[href=\"#manually-download-the-triton-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Manually download the Triton dependencies<a class=\"headerlink\" href=\"#manually-download-the-triton-dependencies\" title=\"Link to this heading\">#</a></h3><p>The Triton dependencies are already downloaded and installed in the preinstalled image.\nIf your network connection is available, you do not need to download the dependencies which will be fetched automatically during the build.</p>", "a[href=\"#build-commands\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 Build Commands<a class=\"headerlink\" href=\"#build-commands\" title=\"Link to this heading\">#</a></h3><p>Before building, you need to execute <code class=\"docutils literal notranslate\"><span class=\"pre\">source</span> <span class=\"pre\">~/env_setup.sh</span></code>. The content of this script is as follows:</p>", "a[href=\"#manually-download-the-flagtree-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Manually download the FlagTree dependencies<a class=\"headerlink\" href=\"#manually-download-the-flagtree-dependencies\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to download the dependencies which will be fetched automatically during the build.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
